select * from br_declare_log

    AND biz_type = #{bizType}
    AND biz_type in #{bt}
    AND biz_table = #{bizTable}
    AND biz_id = #{bizId}
    AND biz_no like concat('%', #{bizNo}, '%')
    AND execute_type = #{executeType}
    AND execute_type in #{et}
    AND uuid like concat('%', #{uuid}, '%')


            AND result_status is null
            AND result_status = #{resultStatus}



        AND (result_status in
        #{rs}
        OR result_status IS NULL
        )

    AND sync_flag = #{syncFlag}
    AND date_format(create_time, '%Y-%m-%d') >= date_format(#{beginTime}, '%Y-%m-%d')
    AND date_format(create_time, '%Y-%m-%d') <= date_format(#{endTime}, '%Y-%m-%d')

order by id desc
